// lib/widgets/staircase_qr_sheet.dart
import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:qr_flutter/qr_flutter.dart';

import '../config/staircase_locations.dart';
import '../models/starting_location.dart';
import 'app_ui.dart';

/// Bottom sheet that renders the scannable QR code for one staircase or all
/// staircases on a floor.
///
/// The payload is generated by [StartingLocation.qrData], so every code is
/// accepted by the app's QR scanner and pins the user at that staircase.
class StaircaseQrSheet extends StatelessWidget {
  final String floorName;
  final List<StartingLocation> staircases;

  const StaircaseQrSheet({
    super.key,
    required this.floorName,
    required this.staircases,
  });

  static Future<void> show(
    BuildContext context, {
    required String floorName,
    required List<StartingLocation> staircases,
  }) {
    return showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      builder: (_) =>
          StaircaseQrSheet(floorName: floorName, staircases: staircases),
    );
  }

  @override
  Widget build(BuildContext context) {
    final isDark = Theme.of(context).brightness == Brightness.dark;
    final isSingle = staircases.length == 1;
    final maxHeight = MediaQuery.sizeOf(context).height * 0.78;

    return Container(
      constraints: BoxConstraints(maxHeight: maxHeight),
      decoration: BoxDecoration(
        color: AppPalette.card(isDark),
        borderRadius: const BorderRadius.vertical(
          top: Radius.circular(AppRadius.sheet),
        ),
        border: Border.all(color: AppPalette.cardBorder(isDark)),
      ),
      child: SafeArea(
        top: false,
        child: SingleChildScrollView(
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              const Center(child: SheetHandle()),
              Padding(
                padding: const EdgeInsets.symmetric(horizontal: 20),
                child: Row(
                  children: [
                    const TintIcon(
                      icon: Icons.stairs,
                      color: AppPalette.brand,
                      size: 40,
                      iconSize: 20,
                    ),
                    const SizedBox(width: 12),
                    Expanded(
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Text(
                            isSingle
                                ? StaircaseLocations.labelFor(staircases.single)
                                : 'Staircase QR Codes',
                            style: Theme.of(context).textTheme.titleMedium
                                ?.copyWith(
                                  fontWeight: FontWeight.bold,
                                  color: isDark
                                      ? AppPalette.mist
                                      : AppPalette.ink,
                                ),
                          ),
                          const SizedBox(height: 2),
                          Text(
                            isSingle
                                ? floorName
                                : '$floorName · ${staircases.length} staircases',
                            style: Theme.of(context).textTheme.bodySmall
                                ?.copyWith(
                                  color: isDark
                                      ? AppPalette.mistSoft
                                      : AppPalette.inkSoft,
                                ),
                          ),
                        ],
                      ),
                    ),
                    IconButton(
                      onPressed: () => Navigator.of(context).pop(),
                      icon: const Icon(Icons.close, size: 20),
                      tooltip: 'Close',
                    ),
                  ],
                ),
              ),
              Padding(
                padding: const EdgeInsets.fromLTRB(20, 4, 20, 12),
                child: Text(
                  isSingle
                      ? 'Scan or print this code and place it at the staircase.'
                      : 'Scan or print a code for each staircase. Every code '
                            'pins the user at that exact staircase.',
                  style: Theme.of(context).textTheme.bodySmall?.copyWith(
                    color: isDark ? AppPalette.mistSoft : AppPalette.inkSoft,
                  ),
                ),
              ),
              if (isSingle)
                Center(
                  child: Padding(
                    padding: const EdgeInsets.fromLTRB(20, 0, 20, 20),
                    child: _StaircaseQrCard(
                      location: staircases.single,
                      floorName: floorName,
                      isDark: isDark,
                      width: 230,
                    ),
                  ),
                )
              else
                SizedBox(
                  height: 292,
                  child: ListView.separated(
                    scrollDirection: Axis.horizontal,
                    padding: const EdgeInsets.fromLTRB(20, 0, 20, 20),
                    itemCount: staircases.length,
                    separatorBuilder: (_, __) => const SizedBox(width: 12),
                    itemBuilder: (context, index) => _StaircaseQrCard(
                      location: staircases[index],
                      floorName: floorName,
                      isDark: isDark,
                    ),
                  ),
                ),
            ],
          ),
        ),
      ),
    );
  }
}

class _StaircaseQrCard extends StatelessWidget {
  final StartingLocation location;
  final String floorName;
  final bool isDark;
  final double width;

  const _StaircaseQrCard({
    required this.location,
    required this.floorName,
    required this.isDark,
    this.width = 200,
  });

  @override
  Widget build(BuildContext context) {
    return Container(
      width: width,
      padding: const EdgeInsets.all(14),
      decoration: BoxDecoration(
        color: isDark ? AppPalette.scaffold(true) : const Color(0xFFF7FBF8),
        borderRadius: BorderRadius.circular(AppRadius.card),
        border: Border.all(
          color: AppPalette.cardBorder(isDark, AppPalette.brand),
        ),
      ),
      child: Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          Container(
            padding: const EdgeInsets.all(6),
            decoration: BoxDecoration(
              color: Colors.white,
              borderRadius: BorderRadius.circular(12),
            ),
            child: QrImageView(
              data: location.qrData,
              version: QrVersions.auto,
              size: 120,
              backgroundColor: Colors.white,
            ),
          ),
          const SizedBox(height: 8),
          Text(
            StaircaseLocations.labelFor(location),
            maxLines: 2,
            textAlign: TextAlign.center,
            overflow: TextOverflow.ellipsis,
            style: Theme.of(context).textTheme.labelLarge?.copyWith(
              fontWeight: FontWeight.w700,
              height: 1.15,
              color: isDark ? AppPalette.mist : AppPalette.ink,
            ),
          ),
          const SizedBox(height: 2),
          Text(
            '$floorName · ${location.id}',
            maxLines: 1,
            textAlign: TextAlign.center,
            overflow: TextOverflow.ellipsis,
            style: Theme.of(context).textTheme.labelSmall?.copyWith(
              color: isDark ? AppPalette.mistSoft : AppPalette.inkSoft,
            ),
          ),
          const SizedBox(height: 4),
          InkWell(
            onTap: () {
              Clipboard.setData(ClipboardData(text: location.qrData));
              ScaffoldMessenger.of(context).showSnackBar(
                SnackBar(
                  content: Text('${location.name} QR payload copied'),
                  duration: const Duration(seconds: 2),
                ),
              );
            },
            borderRadius: BorderRadius.circular(8),
            child: const Padding(
              padding: EdgeInsets.symmetric(horizontal: 6, vertical: 3),
              child: Row(
                mainAxisSize: MainAxisSize.min,
                children: [
                  Icon(Icons.copy, size: 12, color: AppPalette.brand),
                  SizedBox(width: 4),
                  Text(
                    'Copy data',
                    style: TextStyle(fontSize: 11, color: AppPalette.brand),
                  ),
                ],
              ),
            ),
          ),
        ],
      ),
    );
  }
}
